class _GreaterValues(list):
    """A list of values greater than a specified number.

    In addition to behaving like the filtered list, equality with a
    boolean follows the example in the issue: it is equal to ``True``
    exactly when every value in the original list is greater than the
    specified number, and equal to ``False`` otherwise.
    """

    def __init__(self, values, all_greater):
        super().__init__(values)
        self._all_greater = all_greater

    def __eq__(self, other):
        if isinstance(other, bool):
            return self._all_greater == other
        return super().__eq__(other)

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result


def greater_specificnum(list, num):
    """Write a function to find all the values in a list that are greater than a specified number."""
    greater_values = []
    all_greater = True
    for value in list:
        if value > num:
            greater_values.append(value)
        else:
            all_greater = False
    return _GreaterValues(greater_values, all_greater)
